import json, sys
path = sys.argv[1]
terms = [t.lower() for t in sys.argv[2:]]
def textof(obj):
    out=[]
    msg = obj.get('message') or {}
    c = msg.get('content')
    if isinstance(c,str): out.append(c)
    elif isinstance(c,list):
        for b in c:
            if isinstance(b,dict):
                if b.get('type')=='text': out.append(b.get('text',''))
                elif b.get('type')=='tool_result':
                    cc=b.get('content')
                    if isinstance(cc,str): out.append(cc)
                    elif isinstance(cc,list):
                        for x in cc:
                            if isinstance(x,dict) and x.get('type')=='text': out.append(x.get('text',''))
                elif b.get('type')=='tool_use':
                    out.append('TOOL_USE '+b.get('name','')+' '+json.dumps(b.get('input',{}))[:500])
    if isinstance(obj.get('content'),str): out.append(obj['content'])
    if obj.get('summary'): out.append('SUMMARY: '+str(obj['summary']))
    return '\n'.join(out)
n=0
with open(path) as f:
    for ln,line in enumerate(f):
        line=line.strip()
        if not line: continue
        try: obj=json.loads(line)
        except: continue
        txt=textof(obj)
        low=txt.lower()
        if any(t in low for t in terms):
            role = (obj.get('message') or {}).get('role') or obj.get('type','?')
